-- Store the HTML part alongside the text one.
--
-- text/plain is auto-generated by the sender's client and is full of
-- artefacts: [cid:...] image references, [Receiver outline] alt text for
-- signature icons, and address<mailto:address> link expansions. Mail clients
-- render the HTML, which is why the same message looks clean in Gmail.
ALTER TABLE messages ADD COLUMN IF NOT EXISTS body_html text;
